116	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
117	    @Override
118	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
119	        // Normalize the address up front so every downstream use (the required-field check,
120	        // household-duplicate detection, the shared household id and the stored/returned value)
121	        // works from the same canonical form.
122	        String normalizedAddress = normalizeAddress(ownerFieldsDto.getAddress());
123	        List<String> missingFields = new ArrayList<>();
124	        if (isBlank(ownerFieldsDto.getFirstName())) {
125	            missingFields.add("firstName");
126	        }
127	        if (isBlank(ownerFieldsDto.getLastName())) {
128	            missingFields.add("lastName");
129	        }
130	        // Reject an address that is blank once normalized (e.g. whitespace-only input).
131	        if (isBlank(normalizedAddress)) {
132	            missingFields.add("address");
133	        }
134	        if (isBlank(ownerFieldsDto.getCity())) {
135	            missingFields.add("city");
136	        }
137	        if (isBlank(ownerFieldsDto.getTelephone())) {
138	            missingFields.add("telephone");
139	        }
140	        if (!missingFields.isEmpty()) {
141	            throw new InvalidOwnerFieldsException(missingFields);
142	        }
143	        // A supplied registration date may not lie in the future: reject with 400 when the caller
144	        // provides a date later than the server's current date. Checked against the raw supplied value
145	        // (before any business-day adjustment) so a future date is never silently accepted.
146	        if (ownerFieldsDto.getRegistrationDate() != null
147	            && ownerFieldsDto.getRegistrationDate().isAfter(LocalDate.now())) {
148	            throw new FutureRegistrationDateException(ownerFieldsDto.getRegistrationDate());
149	        }
150	        // Determine the effective registration date up front so every downstream use (the daily
151	        // create-limit, the stored value and anything derived from it such as the membership number's
152	        // year segment) works from the same business-day-adjusted date. The effective date is the
153	        // supplied value when present, otherwise the server's current date; a weekend date is rolled
154	        // forward to the following Monday.
155	        LocalDate effectiveRegistrationDate = ownerFieldsDto.getRegistrationDate() != null
156	            ? ownerFieldsDto.getRegistrationDate()
157	            : LocalDate.now();
158	        effectiveRegistrationDate = toBusinessDay(effectiveRegistrationDate);
159	        // Reject the request once the day's owner-creation limit is reached: when 100 or more owners
160	        // already carry this adjusted business day's registration date, no further owners may be
161	        // created for that day.
162	        int ownersRegisteredToday = countOwnersRegisteredOn(effectiveRegistrationDate);
163	        if (ownersRegisteredToday >= MAX_OWNERS_PER_DAY) {
164	            throw new DailyOwnerLimitExceededException(effectiveRegistrationDate);
165	        }
166	        // Flag a bulk signup once more than 80 owners have already been created for this
167	        // business day, sharing the same daily accumulation path as the create-limit rule above.
168	        boolean bulkSignupWarning = ownersRegisteredToday > BULK_SIGNUP_WARNING_THRESHOLD;
169	        // Reject the request when the owner's city is already full: a city that already holds the
170	        // maximum of 50 owners (compared case-insensitively, as elsewhere) accepts no more.
171	        if (countOwnersInCity(ownerFieldsDto.getCity()) >= MAX_OWNERS_PER_CITY) {
172	            throw new CityAtCapacityException(ownerFieldsDto.getCity());
173	        }
174	        // Postcode is optional; when present it must be a 4-digit value that is valid for the
175	        // owner's city per the fixed region ranges. A malformed or out-of-range postcode is
176	        // rejected with a 400. An absent postcode leaves the request contract unchanged.
177	        validatePostcode(ownerFieldsDto.getCity(), ownerFieldsDto.getPostcode());
178	        // Normalize the telephone into E.164 form; a number that cannot form a valid
179	        // E.164 value is rejected with a 400.
180	        String normalizedTelephone = toE164(ownerFieldsDto.getTelephone());
181	        // Email is optional; when present it must be a syntactically valid address and is
182	        // stored lower-cased. An invalid address is rejected with a 400.
183	        String normalizedEmail = normalizeEmail(ownerFieldsDto.getEmail());
184	        // Derive the household id up front (a deterministic function of the normalized last name and
185	        // address) whenever the caller opts into a shared household, so it can feed the identity key
186	        // below. Owners not admitted into a household have a null household id.
187	        String normalizedLastName = collapse(ownerFieldsDto.getLastName());
188	        String householdId = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())
189	            ? householdId(normalizedLastName, normalizedAddress)
190	            : null;
191	        // All duplicate detection is consolidated into a single derived identity key:
192	        // 'normalizedTelephone + | + (email or empty) + | + householdId'. Because the telephone is
193	        // part of the key, two members of the same household (same householdId) with different
194	        // telephones have different keys and are both allowed; only an exact whole-key match is a
195	        // duplicate. Reject with 409 when a new owner's whole identity key equals an existing one's.
196	        String identityKey = identityKey(normalizedTelephone, normalizedEmail, householdId);
197	        boolean identityInUse = this.clinicService.findAllOwners().stream()
198	            .anyMatch(existing -> identityKey.equals(
199	                identityKey(existing.getTelephone(), existing.getEmail(), existing.getHouseholdId())));
200	        if (identityInUse) {
201	            throw new DuplicateOwnerIdentityException(identityKey);
202	        }
203	        // For a shared household, backfill the shared identifier onto any existing member of this
204	        // household so the whole household carries the same stable value.
205	        if (householdId != null) {
206	            for (Owner existing : this.clinicService.findAllOwners()) {
207	                if (collapse(existing.getLastName()).equals(normalizedLastName)
208	                    && normalizeAddress(existing.getAddress()).equals(normalizedAddress)
209	                    && !householdId.equals(existing.getHouseholdId())) {
210	                    existing.setHouseholdId(householdId);
211	                    this.clinicService.saveOwner(existing);
212	                }
213	            }
214	        }
215	        HttpHeaders headers = new HttpHeaders();
216	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
217	        owner.setAddress(normalizedAddress);
218	        owner.setTelephone(normalizedTelephone);
219	        owner.setEmail(normalizedEmail);
220	        owner.setHouseholdId(householdId);
221	        // Record how many existing owners (before this create) share this owner's first and last
222	        // name, compared case-insensitively. Computed against the current owners so the new owner
223	        // itself is never counted.
224	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
225	        // Record the size of this owner's household (owners sharing the same householdId) after this
226	        // create: the existing members already stamped with the shared identifier plus this new
227	        // owner. An owner not admitted into any household is a household of one.
228	        owner.setHouseholdSize(countHouseholdMembers(householdId) + 1);
229	        // Persist the bulk-signup flag computed above so it is returned on subsequent reads.
230	        owner.setBulkSignupWarning(bulkSignupWarning);
231	        // Store the business-day-adjusted effective registration date computed above. This defaults
232	        // to the server's current date when none was supplied and rolls any weekend date forward to
233	        // the following Monday, so everything derived from it (e.g. the membership number's year
234	        // segment) uses the adjusted date.
235	        owner.setRegistrationDate(effectiveRegistrationDate);
236	        // Assign the customer code: '<REGION>-<HASH8>' where REGION is the region derived from the
237	        // owner's postcode (falling back to the city-to-region table, else 'UNKNOWN', matching the
238	        // locality derivation) and HASH8 is the first 8 upper-case hex characters of
239	        // SHA-256(normalizedTelephone + lastName). Sequence numbers are no longer used.
240	        owner.setCustomerCode(customerCode(
241	            deriveRegion(owner.getPostcode(), owner.getCity()), normalizedTelephone, owner.getLastName()));
242	        // Soft-match detection: an owner that cleared the hard-duplicate identity check above may
243	        // still resemble an existing owner when it shares that owner's last name and postcode but
244	        // carries a different telephone. Flag such an owner as a possible duplicate, recording the
245	        // matching owner's id; otherwise the flag is false with no matched id.
246	        Owner possibleDuplicateOwner = findPossibleDuplicate(
247	            owner.getLastName(), owner.getPostcode(), normalizedTelephone);
248	        owner.setPossibleDuplicate(possibleDuplicateOwner != null);
249	        owner.setPossibleDuplicateOf(possibleDuplicateOwner == null ? null : possibleDuplicateOwner.getId());
250	        this.clinicService.saveOwner(owner);
251	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
252	        // Emit an audit trail line for the successful create, carrying the owner id, the assigned
253	        // customer code, the effective registration date and the numeric membership level.
254	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={}",
255	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), ownerDto.getMembershipLevel());
256	        headers.setLocation(UriComponentsBuilder.newInstance()
257	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
258	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
259	    }
