263	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
264	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
265	        if (currentOwner == null) {
266	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
267	        }
268	        currentOwner.setAddress(ownerFieldsDto.getAddress());
269	        currentOwner.setCity(ownerFieldsDto.getCity());
270	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
271	        currentOwner.setLastName(ownerFieldsDto.getLastName());
272	        currentOwner.setTelephone(toE164(ownerFieldsDto.getTelephone()));
273	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
274	        this.clinicService.saveOwner(currentOwner);
275	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
276	    }
