315	            if (currentPet != null) {
316	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
317	                currentPet.setName(petFieldsDto.getName());
318	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
319	                this.clinicService.savePet(currentPet);
320	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
321	            }
322	        }
323	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
324	    }
