355	    private static boolean isBlank(String value) {
356	        return value == null || value.trim().isEmpty();
357	    }
358	
359	    /**
360	     * Normalize an owner identity field for household-duplicate comparison: trim, collapse every
361	     * run of whitespace to a single space, and lower-case. Used so that last name and address are
362	     * compared case-insensitively with collapsed whitespace.
363	     */
364	    private static String collapse(String value) {
365	        if (value == null) {
366	            return "";
367	        }
368	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
369	    }
370	
371	    /**
372	     * Common street-type abbreviations expanded during address normalization.
373	     */
374	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
375	        "ST", "STREET",
376	        "RD", "ROAD",
377	        "AVE", "AVENUE");
378	
379	    /**
380	     * Normalize an owner address into its canonical stored/compared form: trim, collapse every run
381	     * of whitespace to a single space, upper-case, and expand common street-type abbreviations
382	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). Returns an empty string for
383	     * a {@code null} or blank input. The transformation is idempotent, so an already-normalized
384	     * address maps to itself.
385	     */
386	    private static String normalizeAddress(String value) {
387	        if (value == null) {
388	            return "";
389	        }
390	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase();
391	        if (collapsed.isEmpty()) {
392	            return "";
393	        }
394	        String[] tokens = collapsed.split(" ");
395	        StringBuilder sb = new StringBuilder(collapsed.length());
396	        for (int i = 0; i < tokens.length; i++) {
397	            if (i > 0) {
398	                sb.append(' ');
399	            }
400	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
401	        }
402	        return sb.toString();
403	    }
404	
405	    /**
406	     * Derive the stable household identifier shared by owners with the same normalized last name
407	     * and address. It is a deterministic function of those two values, so every member of a
408	     * household independently derives the same identifier: the first 12 upper-case hex characters
409	     * of {@code SHA-256(normalizedLastName + '\n' + normalizedAddress)}.
410	     */
411	    private static String householdId(String normalizedLastName, String normalizedAddress) {
412	        try {
413	            byte[] digest = MessageDigest.getInstance("SHA-256")
414	                .digest((normalizedLastName + "\n" + normalizedAddress).getBytes(StandardCharsets.UTF_8));
415	            StringBuilder sb = new StringBuilder(digest.length * 2);
416	            for (byte b : digest) {
417	                sb.append(String.format("%02x", b));
418	            }
419	            return sb.substring(0, 12).toUpperCase();
420	        }
421	        catch (NoSuchAlgorithmException e) {
422	            throw new IllegalStateException("SHA-256 not available", e);
423	        }
424	    }
425	
426	    /**
427	     * Derive the identity key into which all duplicate detection is consolidated:
428	     * {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}. A null email or
429	     * household id contributes an empty segment. Two owners are duplicates only when their whole
430	     * identity keys are equal.
431	     */
432	    private static String identityKey(String telephone, String email, String householdId) {
433	        return (telephone == null ? "" : telephone)
434	            + "|" + (email == null ? "" : email)
435	            + "|" + (householdId == null ? "" : householdId);
436	    }
437	
438	    /**
439	     * Count the existing owners that share the given first and last name, compared
440	     * case-insensitively. Called before the new owner is saved, so the returned value reflects the
441	     * namesakes that already existed at creation time (the new owner itself is not included).
442	     */
443	    private int countNamesakes(String firstName, String lastName) {
444	        return (int) this.clinicService.findAllOwners().stream()
445	            .filter(existing -> existing.getFirstName() != null && existing.getLastName() != null)
446	            .filter(existing -> existing.getFirstName().equalsIgnoreCase(firstName)
447	                && existing.getLastName().equalsIgnoreCase(lastName))
448	            .count();
449	    }
450	
451	    /**
452	     * Count the existing owners that already belong to the given household (i.e. carry the same
453	     * non-null householdId). Called after any existing members have been backfilled with the shared
454	     * identifier but before the new owner is saved, so the returned value reflects the members that
455	     * already existed at creation time (the new owner itself is not included). Returns 0 when the
456	     * new owner is not part of any household ({@code householdId} is null).
457	     */
458	    private int countHouseholdMembers(String householdId) {
459	        if (householdId == null) {
460	            return 0;
461	        }
462	        return (int) this.clinicService.findAllOwners().stream()
463	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
464	            .count();
465	    }
466	
467	    /**
468	     * Find an existing owner that this new owner is a possible (soft) duplicate of: one that shares
469	     * the new owner's last name (compared case-insensitively) and postcode while carrying a different
470	     * (already normalized) telephone. When several existing owners match, the earliest (lowest id) is
471	     * returned so the result is deterministic. Returns {@code null} when there is no such owner —
472	     * including when the new owner has no last name or postcode, since a shared postcode is required
473	     * to match.
474	     */
475	    private Owner findPossibleDuplicate(String lastName, String postcode, String normalizedTelephone) {
476	        if (isBlank(lastName) || isBlank(postcode)) {
477	            return null;
478	        }
479	        return this.clinicService.findAllOwners().stream()
480	            .filter(existing -> lastName.equalsIgnoreCase(existing.getLastName()))
481	            .filter(existing -> postcode.equals(existing.getPostcode()))
482	            .filter(existing -> !normalizedTelephone.equals(existing.getTelephone()))
483	            .min(java.util.Comparator.comparing(Owner::getId))
484	            .orElse(null);
485	    }
486	
487	    /**
488	     * The maximum number of owners a single city may contain. Once a city holds this many owners a
489	     * request to create another owner in it is rejected as a conflict.
490	     */
491	    private static final int MAX_OWNERS_PER_CITY = 50;
492	
493	    /**
494	     * Count the existing owners registered in the given city, compared case-insensitively (as in
495	     * {@link #nextCustomerCode}). Called before the new owner is saved, so the returned value
496	     * reflects the owners that already existed at creation time.
497	     */
498	    private int countOwnersInCity(String city) {
499	        return (int) this.clinicService.findAllOwners().stream()
500	            .filter(existing -> existing.getCity() != null && existing.getCity().equalsIgnoreCase(city))
501	            .count();
502	    }
503	
504	    /**
505	     * The maximum number of owners that may be created on a single day. Once this many owners
506	     * already carry a given day's registration date, a request to create another owner that day is
507	     * rejected with a 429.
508	     */
509	    private static final int MAX_OWNERS_PER_DAY = 100;
510	
511	    /**
512	     * The number of owners that may be created on a single day before the bulk-signup warning is
513	     * flagged. Once more than this many owners already carry a given day's registration date, a
514	     * newly created owner is flagged with {@code bulkSignupWarning} set true.
515	     */
516	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
517	
518	    /**
519	     * Count the existing owners whose registration date is the given day. Called before the new
520	     * owner is saved, so the returned value reflects the owners that already existed at creation
521	     * time.
522	     */
523	    private int countOwnersRegisteredOn(LocalDate date) {
524	        return (int) this.clinicService.findAllOwners().stream()
525	            .filter(existing -> date.equals(existing.getRegistrationDate()))
526	            .count();
527	    }
528	
529	    /**
530	     * Roll a date forward onto a business day: a Saturday or Sunday is advanced to the following
531	     * Monday, while a weekday is returned unchanged. Used so the effective registration date (whether
532	     * supplied or defaulted) always falls on a business day.
533	     */
534	    private static LocalDate toBusinessDay(LocalDate date) {
535	        return switch (date.getDayOfWeek()) {
536	            case SATURDAY -> date.plusDays(2);
537	            case SUNDAY -> date.plusDays(1);
538	            default -> date;
539	        };
540	    }
541	
542	    /**
543	     * Build the customer code for a new owner: {@code '<REGION>-<HASH8>'} where REGION is the region
544	     * derived from the owner's postcode/city and HASH8 is the first 8 upper-case hex characters of
545	     * {@code SHA-256(normalizedTelephone + lastName)} (e.g. {@code 'NSW-1A2B3C4D'}).
546	     */
547	    private static String customerCode(String region, String normalizedTelephone, String lastName) {
548	        return region + "-" + hash8(normalizedTelephone + (lastName == null ? "" : lastName));
549	    }
550	
551	    /**
552	     * First 8 upper-case hex characters of {@code SHA-256(input)}.
553	     */
554	    private static String hash8(String input) {
555	        try {
556	            byte[] digest = MessageDigest.getInstance("SHA-256")
557	                .digest(input.getBytes(StandardCharsets.UTF_8));
558	            StringBuilder sb = new StringBuilder(digest.length * 2);
559	            for (byte b : digest) {
560	                sb.append(String.format("%02x", b));
561	            }
562	            return sb.substring(0, 8).toUpperCase();
563	        }
564	        catch (NoSuchAlgorithmException e) {
565	            throw new IllegalStateException("SHA-256 not available", e);
566	        }
567	    }
568	
569	    /**
570	     * Derive the owner's region, preferring the postcode: look up the region by postcode range first
571	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099), then fall back to the city-to-region table
572	     * (Sydney-&gt;NSW, Melbourne-&gt;VIC, Brisbane-&gt;QLD) when the postcode is absent or in no known
573	     * range. Returns {@code 'UNKNOWN'} when neither source resolves a region. This mirrors the
574	     * mapper's locality derivation, so the customer code's region segment and the owner's locality
575	     * always agree.
576	     */
577	    private static String deriveRegion(String postcode, String city) {
578	        if (postcode != null && postcode.matches("\\d{4}")) {
579	            int value = Integer.parseInt(postcode);
580	            for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
581	                int[] range = entry.getValue();
582	                if (value >= range[0] && value <= range[1]) {
583	                    return entry.getKey();
584	                }
585	            }
586	        }
587	        if (city == null) {
588	            return "UNKNOWN";
589	        }
590	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
591	    }
592	
593	    /**
594	     * The fixed city-to-region table used to validate a supplied postcode against the owner's city
595	     * (Sydney-&gt;NSW, Melbourne-&gt;VIC, Brisbane-&gt;QLD). A city not present here has no known region
596	     * and accepts any 4-digit postcode.
597	     */
598	    private static final Map<String, String> CITY_REGION = Map.of(
599	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
600	
601	    /**
602	     * The fixed region-to-postcode ranges (inclusive): NSW 2000-2099, VIC 3000-3099, QLD 4000-4099.
603	     * Each entry is a two-element {@code {low, high}} array.
604	     */
605	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
606	        "NSW", new int[] {2000, 2099},
607	        "VIC", new int[] {3000, 3099},
608	        "QLD", new int[] {4000, 4099});
609	
610	    /**
611	     * Validate an optional owner postcode. Does nothing when no postcode was supplied (the field is
612	     * optional and the request contract stays backward-compatible). When supplied it must be exactly
613	     * 4 digits and, if the city maps to a known region, must fall within that region's inclusive
614	     * range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with no known region accepts any
615	     * 4-digit postcode. A malformed or out-of-range postcode throws an
616	     * {@link InvalidOwnerFieldsException} so the request is rejected with a 400.
617	     */
618	    private static void validatePostcode(String city, String postcode) {
619	        if (postcode == null || postcode.isEmpty()) {
620	            return;
621	        }
622	        if (!postcode.matches("\\d{4}")) {
623	            throw new InvalidOwnerFieldsException(List.of("postcode"));
624	        }
625	        String region = city == null ? null : CITY_REGION.get(city);
626	        if (region == null) {
627	            return;
628	        }
629	        int[] range = REGION_POSTCODES.get(region);
630	        int value = Integer.parseInt(postcode);
631	        if (value < range[0] || value > range[1]) {
632	            throw new InvalidOwnerFieldsException(List.of("postcode"));
633	        }
634	    }
635	
636	    /**
637	     * Required national-number length for each E.164 country calling code we validate: a
638	     * {@code '+61'} (Australia) number carries 9 national digits and a {@code '+1'} (NANP) number
639	     * carries 10. Country codes not listed here are accepted at any (generally valid) length.
640	     */
641	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS = Map.of(
642	        "1", 10,
643	        "61", 9);
644	
645	    /**
646	     * Convert a raw telephone into E.164 form. Spaces, dashes and brackets are stripped. A leading
647	     * {@code '+'} with its country code is preserved; otherwise the Australian country code
648	     * {@code '+61'} is assumed and a single leading {@code '0'} is dropped from the national digits.
649	     * The result must be a {@code '+'} followed by 8 to 15 digits, and for a recognised country code
650	     * its national-number length must match ({@code '+61'} requires 9 national digits, {@code '+1'}
651	     * requires 10); otherwise an {@link InvalidOwnerFieldsException} is thrown so the request is
652	     * rejected with a 400.
653	     */
654	    private static String toE164(String raw) {
655	        String cleaned = raw.trim().replaceAll("[\\s()\\-]", "");
656	        boolean hasCountryCode = cleaned.startsWith("+");
657	        String digits = hasCountryCode ? cleaned.substring(1) : cleaned;
658	        if (!digits.matches("\\d+")) {
659	            throw new InvalidOwnerFieldsException(List.of("telephone"));
660	        }
661	        if (!hasCountryCode) {
662	            if (digits.startsWith("0")) {
663	                digits = digits.substring(1);
664	            }
665	            digits = "61" + digits;
666	        }
667	        if (digits.length() < 8 || digits.length() > 15) {
668	            throw new InvalidOwnerFieldsException(List.of("telephone"));
669	        }
670	        // For a recognised country code, the national number (the digits after the code) must be
671	        // exactly the expected length for that country. Match the longest known code so a shorter
672	        // code that is a prefix of another cannot mask it.
673	        for (int codeLength = 3; codeLength >= 1; codeLength--) {
674	            if (digits.length() <= codeLength) {
675	                continue;
676	            }
677	            String countryCode = digits.substring(0, codeLength);
678	            Integer requiredNationalLength = NATIONAL_NUMBER_LENGTHS.get(countryCode);
679	            if (requiredNationalLength != null) {
680	                if (digits.length() - codeLength != requiredNationalLength) {
681	                    throw new InvalidOwnerFieldsException(List.of("telephone"));
682	                }
683	                break;
684	            }
685	        }
686	        return "+" + digits;
687	    }
688	
689	    /**
690	     * Pragmatic syntactic check for an email address: a non-empty local part, an {@code @},
691	     * and a domain with at least one dot-separated label, none of which contain whitespace or
692	     * a second {@code @}. This is deliberately permissive but rejects obviously malformed input.
693	     */
694	    private static final Pattern EMAIL_PATTERN =
695	        Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
696	
697	    /**
698	     * Validate and normalize an optional owner email. Returns {@code null} when no email was
699	     * supplied (the field is optional). When supplied it must be a syntactically valid address,
700	     * otherwise an {@link InvalidOwnerFieldsException} is thrown so the request is rejected with a
701	     * 400. A valid address is returned lower-cased.
702	     */
703	    private static String normalizeEmail(String email) {
704	        if (email == null || email.isEmpty()) {
705	            return null;
706	        }
707	        String trimmed = email.trim();
708	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
709	            throw new InvalidOwnerFieldsException(List.of("email"));
710	        }
711	        return trimmed.toLowerCase();
712	    }
713	}
