18	@Mapper(uses = PetMapper.class)
19	public interface OwnerMapper {
20	
21	    @Mapping(target = "displayName",
22	        expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
23	    @Mapping(target = "initials",
24	        expression = "java(Character.toUpperCase(owner.getFirstName().charAt(0)) + \".\" "
25	            + "+ Character.toUpperCase(owner.getLastName().charAt(0)) + \".\")")
26	    @Mapping(target = "membershipNumber",
27	        expression = "java(membershipNumber(owner))")
28	    @Mapping(target = "membershipLevel",
29	        expression = "java(membershipLevel(owner))")
30	    @Mapping(target = "locality",
31	        expression = "java(locality(owner))")
32	    @Mapping(target = "contactPreference",
33	        expression = "java(contactPreference(owner))")
34	    @Mapping(target = "identityKey",
35	        expression = "java(identityKey(owner))")
36	    @Mapping(target = "checkDigit",
37	        expression = "java(checkDigit(owner))")
38	    @Mapping(target = "ageBand",
39	        expression = "java(ageBand(owner))")
40	    @Mapping(target = "sharesHousehold", ignore = true)
41	    OwnerDto toOwnerDto(Owner owner);
42	
43	    /**
44	     * Derive the owner's age band from the supplied birthDate, evaluated against the owner's
45	     * registrationDate: 'MINOR' when under 18, 'ADULT' when 18 to 64 inclusive, and 'SENIOR' when
46	     * 65 or older. Returns null when no birthDate was supplied (or no registrationDate is available)
47	     * so owners without a birth date serialize cleanly.
48	     */
49	    default String ageBand(Owner owner) {
50	        java.time.LocalDate birthDate = owner.getBirthDate();
51	        java.time.LocalDate registrationDate = owner.getRegistrationDate();
52	        if (birthDate == null || registrationDate == null) {
53	            return null;
54	        }
55	        int age = java.time.Period.between(birthDate, registrationDate).getYears();
56	        if (age < 18) {
57	            return "MINOR";
58	        }
59	        if (age < 65) {
60	            return "ADULT";
61	        }
62	        return "SENIOR";
63	    }
64	
65	    /**
66	     * Compute the owner's check digit: a single Luhn check digit (0-9) over the digits contained in
67	     * the customerCode. Returns null when no customerCode has been assigned so owners without a code
68	     * serialize cleanly.
69	     */
70	    default Integer checkDigit(Owner owner) {
71	        String customerCode = owner.getCustomerCode();
72	        if (customerCode == null) {
73	            return null;
74	        }
75	        int sum = 0;
76	        boolean dbl = true;
77	        for (int i = customerCode.length() - 1; i >= 0; i--) {
78	            char c = customerCode.charAt(i);
79	            if (c < '0' || c > '9') {
80	                continue;
81	            }
82	            int d = c - '0';
83	            if (dbl) {
84	                d *= 2;
85	                if (d > 9) {
86	                    d -= 9;
87	                }
88	            }
89	            sum += d;
90	            dbl = !dbl;
91	        }
92	        return (10 - (sum % 10)) % 10;
93	    }
94	
95	    /**
96	     * Derive the owner's identity key, the single value into which all duplicate detection is
97	     * consolidated: {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}. Two
98	     * owners are duplicates only when their whole identity keys are equal. A null email or
99	     * householdId contributes an empty segment.
100	     */
101	    default String identityKey(Owner owner) {
102	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
103	        String email = owner.getEmail() == null ? "" : owner.getEmail();
104	        String householdId = owner.getHouseholdId() == null ? "" : owner.getHouseholdId();
105	        return telephone + "|" + email + "|" + householdId;
106	    }
107	
108	    /**
109	     * Determine the owner's preferred contact channel: 'EMAIL' when an email address is present,
110	     * otherwise 'PHONE'.
111	     */
112	    default String contactPreference(Owner owner) {
113	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isEmpty();
114	        return hasEmail ? "EMAIL" : "PHONE";
115	    }
116	
117	    /**
118	     * Build the owner's membership number, formatted '&lt;customerCode&gt;-M&lt;YY&gt;' where YY is
119	     * the last two digits of the registrationDate year. Returns null when either source field is
120	     * absent so owners without an assigned code or registration date serialize cleanly.
121	     */
122	    default String membershipNumber(Owner owner) {
123	        if (owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
124	            return null;
125	        }
126	        return String.format("%s-M%02d", owner.getCustomerCode(),
127	            owner.getRegistrationDate().getYear() % 100);
128	    }
129	
130	    /**
131	     * Determine the owner's numeric membership level, assigned at creation. Starts at 1; add 1 when
132	     * an email address is present; add 1 when the owner has no namesakes (namesakeCount is 0);
133	     * capped at 3 (level 4 is reserved for tenure).
134	     */
135	    default Integer membershipLevel(Owner owner) {
136	        int level = 1;
137	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isEmpty();
138	        if (hasEmail) {
139	            level++;
140	        }
141	        boolean noNamesakes = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
142	        if (noNamesakes) {
143	            level++;
144	        }
145	        return Math.min(level, 3);
146	    }
147	
148	    /**
149	     * The fixed city-to-region table used to derive an owner's locality when the postcode is absent
150	     * or falls in no known range.
151	     */
152	    java.util.Map<String, String> CITY_REGION = java.util.Map.of(
153	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
154	
155	    /**
156	     * Region -&gt; inclusive 4-digit postcode range {low, high}: NSW 2000-2099, VIC 3000-3099,
157	     * QLD 4000-4099.
158	     */
159	    java.util.Map<String, int[]> REGION_POSTCODES = java.util.Map.of(
160	        "NSW", new int[] {2000, 2099},
161	        "VIC", new int[] {3000, 3099},
162	        "QLD", new int[] {4000, 4099});
163	
164	    /**
165	     * Derive the owner's locality (canonical region), preferring the postcode: look up the region by
166	     * postcode range first (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099), and only fall back to the
167	     * city-to-region table (Sydney-&gt;NSW, Melbourne-&gt;VIC, Brisbane-&gt;QLD) when the postcode is
